content:
{
  "code": ".btn-primary,
.btn-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

#confirmation .btn-secondary {
  margin-top: var(--space-lg);
}

[hidden],
[style*="display: none"] {
  display: none !important;
}

@media (prefers-reduced-motion: reduce) {
  .catalogue-card,
  .btn-detail {
    transition: none;
  }

  #booking-section {
    scroll-behavior: auto;
  }
}

@media (max-width: 390px) {
  .editorial-hero {
    padding: var(--space-md);
    gap: var(--space-md);
  }

  .hero-content h2 {
    font-size: 24px;
  }

  .pottery-illustration {
    height: 160px;
  }

  .catalogue-card {
    padding: var(--space-md);
  }

  .card-meta {
    flex-wrap: wrap;
  }

  #booking-section,
  #confirmation {
    padding: var(--space-md);
  }

  main {
    padding: 0 var(--space-sm);
  }
}

@media (max-width: 320px) {
  .masthead h1 {
    font-size: 24px;
  }

  .hero-content h2 {
    font-size: 24px;
  }

  .pottery-illustration {
    height: 140px;
  }

  .btn-primary,
  .btn-detail {
    width: 100%;
  }
}"
}
